"""Abilities.md generator: a human-readable feature list in the data folder.

The files are rewritten on every sidecar start so that they always match the
running version. The UI card opens Abilities_RU.md; the English twin exists for
issue reports and for anyone who prefers English.
"""

from __future__ import annotations

from pathlib import Path

from . import __version__

__all__ = ["RU_TEMPLATE", "EN_TEMPLATE", "abilities_paths", "ensure_files"]

RU_TEMPLATE = '# Возможности VoiceRunaCore\n\n_Версия {version}. Файл обновляется автоматически при запуске ассистента._\n\n## Как меня разбудить\n\n- Скажи имя ассистента (по умолчанию «вокс») и сразу команду: «вокс, открой блокнот».\n- Или нажми **Ctrl+Alt+V**: окно откроется и ассистент начнёт слушать; повторное нажатие сворачивает в трей.\n- После ответа есть **5 секунд**, чтобы продолжить диалог без имени.\n\n## Команды: плагины\n\nЯдро отвечает только за микрофон, распознавание, синтез речи и интерфейс. Все команды\nживут в плагинах, поэтому набор возможностей можно менять без переустановки:\n\n- **Запуск программ** `apps_launcher` — «открой блокнот», «запусти калькулятор»,\n  «открой папку Загрузки», «открой файл отчёт.pdf в документах».\n  Программы запускаются только из белого списка `apps.json` («Настройки → Программы»).\n- **Громкость и файлы** `system_tools` — «громче», «тише», «выключи звук»,\n  «включи звук», «громкость 50%»; «создай файл заметка.txt», «создай файл идеи.md с текстом …».\n  Файлы создаются **только** в `%USERPROFILE%\\Documents\\VoiceRunaCore` и только .txt/.md.\n- **Время и погода** `basic_info` — «который час», «сколько времени»,\n  «какая погода», «погода в Москве» (город по умолчанию — в настройках).\n\n## Управление плагинами\n\n- «Настройки → **Плагины**»: список с тумблерами Вкл/Выкл, как в VS Code.\n- Выключение плагина **сразу** убирает его команды, перезапуск не нужен.\n- Плагины лежат в `%APPDATA%\\VoiceRunaCore\\plugins`.\n- При первом запуске дефолтные плагины копируются туда автоматически; если их\n  отредактировать, они не перезапишутся.\n\n### Как добавить свой плагин\n\n1. Открой `%APPDATA%\\VoiceRunaCore\\plugins`.\n2. Создай папку, внутри — `plugin.py` с классом-наследником `BasePlugin`.\n3. Опиши инструменты в `get_tools()` (имя, описание, параметры, async-обработчик).\n4. Перезапусти ассистента и включи плагин во вкладке «Плагины».\n\n## Диалог и история\n\n- Ассистент отвечает голосом и ведёт историю в окне.\n- «повтори» — повторит последнюю фразу; кнопка микрофона — слушать без имени.\n- Esc — свернуть окно; пауза микрофона и выход — в меню иконки в трее.\n- Любой вопрос (не команда) уходит в LLM: знания, объяснения, болтовня.\n\n## Настройки\n\n- **Звук** — устройства ввода/вывода, проверка, калибровка микрофона, диагностика.\n- **Голос** — движок синтеза (Piper/edge/SAPI), голос, скорость, свои голоса Piper.\n- **Модели** — провайдеры LLM, ключи API, выбор модели.\n- **Программы** — белый список приложений.\n- **Плагины** — включение и выключение плагинов, список их инструментов.\n- **Прочее** — имя и слово-будильник, хоткей, окно follow-up, фразы ошибок, город, логи.\n\n## Справка и данные\n\n- Скажи «что ты умеешь» — в чате появится карточка, открывающая этот файл.\n- Данные и настройки: `%APPDATA%\\VoiceRunaCore`.\n- Логи: `%APPDATA%\\VoiceRunaCore\\logs\\sidecar.log`.\n\n_Работает локально: микрофон, распознавание, синтез и инструменты — на этом компьютере.\nВ сеть уходят только запросы к LLM и погоде._'

EN_TEMPLATE = '# VoiceRunaCore abilities\n\n_Version {version}. This file is refreshed automatically when the assistant starts._\n\n## Waking me up\n\n- Say the assistant name (default "вокс") followed by a command: "вокс, open notepad".\n- Or press **Ctrl+Alt+V**: the window opens and listening starts; press again to hide to tray.\n- After an answer you have **5 seconds** to continue the dialogue without the name.\n\n## Commands: plugins\n\nThe core only handles the microphone, speech recognition, synthesis and the UI. Every\ncommand lives in a plugin, so the feature set changes without reinstalling:\n\n- **Apps launcher** `apps_launcher` — "open notepad", "launch calculator",\n  "open the Downloads folder", "open file report.pdf in documents".\n  Apps launch only from the `apps.json` whitelist (Settings -> Programs).\n- **Volume and files** `system_tools` — "louder", "quieter", "mute",\n  "unmute", "volume 50%"; "create file notes.txt", "create file ideas.md with text ...".\n  Files are created **only** in `%USERPROFILE%\\Documents\\VoiceRunaCore` and only as .txt/.md.\n- **Time and weather** `basic_info` — "what time is it",\n  "what\'s the weather", "weather in Moscow" (default city is set in Settings).\n\n## Managing plugins\n\n- Settings -> **Plugins**: a list with VS Code style on/off switches.\n- Disabling a plugin removes its commands **immediately**, no restart needed.\n- Plugins live in `%APPDATA%\\VoiceRunaCore\\plugins`.\n- On the first run the default plugins are copied there automatically; if you edit\n  them, they are never overwritten.\n\n### Adding your own plugin\n\n1. Open `%APPDATA%\\VoiceRunaCore\\plugins`.\n2. Create a folder with a `plugin.py` exposing a subclass of `BasePlugin`.\n3. Describe tools in `get_tools()` (name, description, parameters, async handler).\n4. Restart the assistant and enable the plugin in the Plugins tab.\n\n## Dialogue and history\n\n- The assistant speaks the answer and keeps the dialogue history in the window.\n- "repeat" re-runs the last phrase; the microphone button listens without the name.\n- Esc hides the window; microphone pause and exit are in the tray menu.\n- Any question (not a command) goes to the LLM: knowledge, explanations, small talk.\n\n## Settings\n\n- **Audio** — input/output devices, tests, microphone calibration, diagnostics.\n- **Voice** — TTS engine (Piper/edge/SAPI), voice, rate, custom Piper voices.\n- **Models** — LLM providers, API keys, model choice.\n- **Programs** — application whitelist.\n- **Plugins** — enable or disable plugins and inspect their tools.\n- **Other** — assistant name and wake word, hotkey, follow-up window, error phrases, city, logs.\n\n## Help and data\n\n- Say "what can you do" — a card will appear in the chat and open this file.\n- Settings and data: `%APPDATA%\\VoiceRunaCore`.\n- Logs: `%APPDATA%\\VoiceRunaCore\\logs\\sidecar.log`.\n\n_Runs locally: microphone, speech recognition, synthesis and tools stay on this computer.\nOnly LLM and weather requests go to the network._'


def abilities_paths(base: Path) -> tuple[Path, Path]:
    """Return (Russian, English) abilities file paths under *base*."""
    return base / "Abilities_RU.md", base / "Abilities_ENG.md"


def ensure_files(base: Path | None = None) -> tuple[Path, Path]:
    """Write both abilities files (UTF-8) and return their paths."""
    from . import paths

    folder = base if base is not None else paths.data_dir()
    folder.mkdir(parents=True, exist_ok=True)
    ru_path, en_path = abilities_paths(folder)
    ru_path.write_text(RU_TEMPLATE.replace("{version}", __version__), encoding="utf-8")
    en_path.write_text(EN_TEMPLATE.replace("{version}", __version__), encoding="utf-8")
    return ru_path, en_path
